    border-radius: $radius-md;

    svg {
      width: 18px;
      height: 18px;
    }
  }

  &__message {
    flex: 1;
    font-size: $font-size-sm;
    font-weight: $font-weight-medium;
    color: $neutral-800;
    line-height: $line-height-base;
  }

  &__action {
    flex-shrink: 0;
    padding: $space-1 $space-3;
    border: none;
    background: transparent;
    border-radius: $radius-md;
    font-size: $font-size-sm;
    font-weight: $font-weight-semibold;
    cursor: pointer;
    transition: all $transition-fast;

    &:focus-visible {
      outline: 2px solid currentColor;
      outline-offset: 2px;
    }
  }

  &__close {
    flex-shrink: 0;
    width: 28px;
    height: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: none;
    background: transparent;
    border-radius: $radius-md;
    cursor: pointer;
    color: $neutral-400;
    transition: all $transition-fast;

    &:hover {
      background: $neutral-100;
      color: $neutral-600;
    }

    &:focus-visible {
      outline: 2px solid $info-500;
      outline-offset: 2px;
    }

    svg {
      width: 16px;
      height: 16px;
    }
  }
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(100%);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

