  }
}

// ============================================
// Modal Block
// ============================================
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.3);
  backdrop-filter: blur(4px);
  @include flex-center;
  padding: $space-4;
  z-index: $z-modal-backdrop;
}

.modal {
  width: 100%;
  max-width: 600px;
  max-height: 90vh;
  overflow-y: auto;
  background: $dash-bg-surface;
  border: 1px solid $dash-border-default;
  border-radius: $radius-xl;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.15);

  // Wider footprint for the multi-field company form (mirrors registration).
  &.wide {
    max-width: 680px;
  }

  &-header {
    @include flex-between;
    padding: $space-4 $space-5;
    border-bottom: 1px solid $dash-border-subtle;

    h3 {
      @include text-heading;
      margin: 0;
      color: $dash-text-primary;
    }
  }

  &-body {
    padding: $space-5;
  }

  &-actions {
    display: flex;
    justify-content: flex-end;
    gap: $space-3;
    margin-top: $space-4;
  }
}

.icon-btn {
  width: 32px;
  height: 32px;
  padding: 0;
  border-radius: $radius-full;
  @include flex-center;
  font-size: $font-size-lg;
  background: $dash-bg-elevated;
  border: 1px solid $dash-border-default;
  color: $dash-text-secondary;

  &:hover {
    background: $dash-bg-hover;
    color: $dash-text-primary;
  }
}

// ============================================
// Details Block (Modal View)
// ============================================
.details {
  display: grid;
  gap: $space-2;

  > div {
    display: grid;
    grid-template-columns: 140px 1fr;
    gap: $space-3;
    padding: $space-3;
    background: $dash-bg-elevated;
    border: 1px solid $dash-border-subtle;
    border-radius: $radius-md;
  }

  dt {
    color: $dash-text-muted;
    font-size: $font-size-xs;
    font-weight: $font-weight-semibold;
  }

  dd {
    margin: 0;
    font-size: $font-size-sm;
    color: $dash-text-primary;
  }
}

// ============================================
// Form Block (Modal Add/Edit)
// ============================================
.form {
  display: grid;
  gap: $space-4;

  label {
    display: flex;
    flex-direction: column;
    gap: $space-2;
    font-size: $font-size-sm;
    color: $dash-text-secondary;
  }

  input,
  select {
    margin-top: 0;
  }
}

.helper {
  color: $dash-text-muted;
  font-size: $font-size-xs;
}

// ============================================
// Company Grid (modal form — mirrors registration)
// ============================================
.company-grid {
  grid-template-columns: 1fr 1fr;
  gap: $space-4 $space-5;

  .span-2 {
    grid-column: 1 / -1;
  }

  // Divider for the "Payout bank account" group inside the modal form.
  .section-title {
    margin: $space-2 0 0;
    padding-top: $space-4;
    border-top: 1px solid $dash-border-default;
    color: $dash-text-primary;
    font-size: $font-size-base;
    font-weight: $font-weight-semibold;
  }

  .modal-actions {
    margin-top: $space-2;
  }

  input[readonly] {
    background: $dash-bg-elevated;
    color: $dash-text-primary;
    cursor: default;
  }

  @media (max-width: 560px) {
    grid-template-columns: 1fr;
  }
}

// ============================================
// Pictogram Upload
// ============================================
.pictogram-upload {
  display: flex;
  flex-direction: column;
  gap: $space-3;

  input[type="file"] {
    font-size: $font-size-sm;
    color: $dash-text-primary;
    cursor: pointer;
  }
}

.pictogram-preview {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: $space-2;

  img {
    max-width: 160px;
    max-height: 160px;
    border-radius: $radius-md;
    border: 2px solid $dash-border-default;
    object-fit: contain;
    background: $dash-bg-elevated;
    padding: $space-2;
  }
}

// ============================================
// Pictogram View (in product detail modal)
// ============================================
.pictogram-view {
  margin-top: $space-4;
  display: flex;
  flex-direction: column;
  gap: $space-2;

  .label {
    font-size: $font-size-sm;
    font-weight: 600;
    color: $dash-text-secondary;
  }
}

.pictogram-img {
  max-width: 200px;
  max-height: 200px;
  border-radius: $radius-md;
  border: 2px solid $dash-border-default;
  object-fit: contain;
  background: $dash-bg-elevated;
  padding: $space-2;
}

