$text-muted:   v.$ink-2;
$success:      v.$ok;
$error:        v.$danger;

// ── Backdrop ──────────────────────────────────────────────────
.scan-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(v.$ink, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: v.$z-modal-backdrop;
  padding: v.$space-4;
}

// ── Modal ─────────────────────────────────────────────────────
.scan-modal {
  position: relative;
  background: $surface;
  border: 1px solid $border;
  border-radius: v.$radius-xl;
  width: 100%;
  max-width: 400px;
  max-height: calc(100dvh - 32px);
  overflow-y: auto;
  padding: v.$space-8 v.$space-6 v.$space-6;
  box-shadow: v.$shadow-pop;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: v.$space-5;

  @media (max-width: 479px) {
    padding: v.$space-8 v.$space-4 v.$space-4;
  }

  &__close {
    position: absolute;
    top: v.$space-2;
    right: v.$space-2;
    width: v.$ctl-h;
    height: v.$ctl-h;
    display: flex;
    align-items: center;
    justify-content: center;
    background: none;
    border: none;
    font-size: 24px;
    color: $text-muted;
    cursor: pointer;
    border-radius: v.$radius-md;
    line-height: 1;
    transition: background 0.15s, color 0.15s;
    &:hover { background: v.$page; color: $text; }
    &:focus-visible { outline: none; box-shadow: v.$focus-ring; }
  }

  &__header {
    text-align: center;
    width: 100%;
    padding-inline: v.$space-8;
  }

  &__title {
    font-size: v.$font-size-lg;
    font-weight: 700;
    color: $text;
    margin: 0 0 v.$space-1;
  }

  &__subtitle {
    font-size: v.$font-size-base;
    color: $text-muted;
    margin: 0;
  }

  // ── Camera ───────────────────────────────────────────────
  &__camera-wrap {
    position: relative;
    width: min(280px, 100%);
    aspect-ratio: 1 / 1;
    border-radius: v.$radius-xl;
    overflow: hidden;
    background: #000;
  }

  &__video {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;

    &--hidden {
      display: none;
    }
  }

  // ── Viewfinder overlay ────────────────────────────────────
  &__viewfinder {
    position: absolute;
    inset: 20px;
    pointer-events: none;
  }

  &__corner {
    position: absolute;
    width: 24px;
    height: 24px;
    border-color: #fff;
    border-style: solid;
    filter: drop-shadow(0 0 2px rgba(0, 0, 0, 0.6));

    &--tl { top: 0; left: 0; border-width: 3px 0 0 3px; border-radius: 4px 0 0 0; }
    &--tr { top: 0; right: 0; border-width: 3px 3px 0 0; border-radius: 0 4px 0 0; }
    &--bl { bottom: 0; left: 0; border-width: 0 0 3px 3px; border-radius: 0 0 0 4px; }
    &--br { bottom: 0; right: 0; border-width: 0 3px 3px 0; border-radius: 0 0 4px 0; }
  }

  &__scan-line {
    position: absolute;
    left: 0; right: 0;
    height: 2px;
    background: $primary;
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.8), 0 0 6px rgba(0, 0, 0, 0.5);
    animation: scan 2s ease-in-out infinite;
  }

