    width: 100%;
    display: flex;
    justify-content: center;
    gap: v.$space-3;

    &--confirm {
      justify-content: space-between;
    }

    .scan-btn {
      flex: 1;
    }

    @media (max-width: 479px) {
      flex-direction: column-reverse;
    }
  }

  // ── State (loading / error) ───────────────────────────────
  &__state {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: v.$space-3;
    padding: v.$space-6 0;
    color: $text-muted;
    font-size: v.$font-size-md;
    text-align: center;

    &--error {
      color: $error;
      background: v.$danger-bg;
      border-radius: v.$radius-md;
      width: 100%;
      padding: v.$space-4;
    }

    &-icon {
      font-size: 2.5rem;
    }
  }
}

// ── Token detail rows ─────────────────────────────────────────
.token-detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: v.$space-3;
  padding: v.$space-3 v.$space-4;
  border-bottom: 1px solid $border;

  &:last-child { border-bottom: none; }

  &__label {
    font-size: v.$font-size-xs;
    font-weight: 600;
    color: $text-muted;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    flex-shrink: 0;
  }

  &__value {
    font-size: v.$font-size-base;
    color: $text;
    font-weight: 500;
    text-align: right;
    min-width: 0;
    overflow-wrap: anywhere;

    &--highlight {
      color: v.$blue-700;
      font-size: v.$font-size-lg;
      font-weight: 700;
      background: $primary-bg;
      padding: 2px v.$space-2;
      border-radius: v.$radius-sm;
    }
  }
}

.mono { font-family: v.$font-family-mono; }

.token-detail-row--mono {
  align-items: flex-start;

  .token-detail-row__value {
    word-break: break-all;
    font-size: v.$font-size-xs;
  }
}

// ── Scan line animation ────────────────────────────────────────
@keyframes scan {
  0%   { top: 0; opacity: 0; }
  10%  { opacity: 1; }
  90%  { opacity: 1; }
  100% { top: 100%; opacity: 0; }
}

// ── Spinner ───────────────────────────────────────────────────
.scan-spinner {
  width: 40px;
  height: 40px;
  border: 3px solid $border;
  border-top-color: $primary;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

// ── Buttons ───────────────────────────────────────────────────
.scan-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: v.$ctl-h;
  padding: v.$space-2 v.$space-5;
  border-radius: v.$radius-md;
  font-size: v.$font-size-md;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background 0.15s, border-color 0.15s, color 0.15s;

  &:focus-visible { outline: none; box-shadow: v.$focus-ring; }

  &--ghost {
    background: $surface;
    border-color: $border;
    color: $text;
    &:hover { background: v.$page; border-color: #C9D2DE; }
  }

  &--confirm {
    background: $primary;
    color: #fff;
    &:hover { background: $primary-dark; }
    &:disabled { opacity: 0.55; cursor: not-allowed; }
  }
